266	func TestDestroyedSampleCannotFlow(t *testing.T) {
267		s, _ := fixedStore(t)
268		mustRegister(t, s, "P", "2.000", "h", "l")
269		hAt := time.Date(2026, 10, 2, 10, 0, 0, 0, time.UTC)
270		rAt := hAt.Add(time.Hour)
271		if _, err := s.Handover(HandoverInput{
272			TransferID: "TR-1", SampleID: "P",
273			FromHolder: "h", FromLocation: "l",
274			ToHolder: "x", ToLocation: "y", HandedOverAt: hAt,
275		}); err != nil {
276			t.Fatal(err)
277		}
278		if _, err := s.Confirm(ConfirmInput{"TR-1", "x", "y", rAt}); err != nil {
279			t.Fatal(err)
280		}
281		dAt := rAt.Add(time.Hour)
282		destroyed, err := s.Destroy(DestroyInput{
283			SampleID: "P", Operator: "x", Location: "y", At: dAt, Reason: "r",
284		})
285		if err != nil {
286			t.Fatalf("destroy: %v", err)
287		}
288	
289		// 不能再分装或发起新的交接。
290		if _, err := s.Split(SplitInput{ParentID: "P", Parts: []SplitPart{{ID: "C", Qty: "0.001"}}}); !errors.Is(err, ErrConflict) {
291			t.Fatalf("已销毁样品分装应 ErrConflict, got %v", err)
292		}
293		newHandover := HandoverInput{
294			TransferID: "TR-2", SampleID: "P",
295			FromHolder: "x", FromLocation: "y",
296			ToHolder: "z", ToLocation: "w", HandedOverAt: dAt.Add(time.Hour),
297		}
298		if _, err := s.Handover(newHandover); !errors.Is(err, ErrConflict) {
299			t.Fatalf("已销毁样品发起新交接应 ErrConflict, got %v", err)
300		}
301	
302		// 既有已确认交接的相同交出请求仍返回原记录，不改变销毁状态、不追加历史。
303		oldHandover := HandoverInput{
304			TransferID: "TR-1", SampleID: "P",
305			FromHolder: "h", FromLocation: "l",
306			ToHolder: "x", ToLocation: "y", HandedOverAt: hAt,
307		}
308		tr, err := s.Handover(oldHandover)
309		if err != nil {
310			t.Fatalf("既有交接相同交出请求应幂等返回原记录, got %v", err)
311		}
312		if !tr.Confirmed || tr.TransferID != "TR-1" {
313			t.Fatalf("返回的不是原交接记录: %+v", tr)
314		}
315		if _, err := s.Confirm(ConfirmInput{"TR-1", "x", "y", rAt}); err != nil {
316			t.Fatalf("既有交接相同接收请求应幂等返回原结果, got %v", err)
317		}
318		got, _ := s.GetSample("P")
319		if got.Destruction == nil || got.Remaining != "0.000" {
320			t.Fatalf("幂等重放后销毁状态应不变: %+v", got)
321		}
322		if len(got.History) != len(destroyed.History) {
323			t.Fatalf("幂等重放不得追加历史: before=%d after=%d",
324				len(destroyed.History), len(got.History))
325		}
326	}
327	
328	// TestDestroyParentChildIndependent 父样与子样的销毁各自独立。
329	func TestDestroyParentChildIndependent(t *testing.T) {
330		s, _ := fixedStore(t)
