387	// TestDestroyPersistsAcrossReopen 重开后销毁信息、剩余量、操作限制与
388	// 幂等判断继续有效。
389	func TestDestroyPersistsAcrossReopen(t *testing.T) {
390		dir := t.TempDir()
391		path := filepath.Join(dir, "destroy.json")
392	
393		s, err := Open(path)
394		if err != nil {
395			t.Fatal(err)
396		}
397		clock := time.Date(2026, 10, 2, 9, 0, 0, 0, time.UTC)
