400		at := clock.Add(time.Hour)
401		first, err := s.Destroy(DestroyInput{
402			SampleID: "P", Operator: "张三", Location: "A", At: at, Reason: "污染",
403		})
404		if err != nil {
405			t.Fatal(err)
406		}
407	
408		s2, err := Open(path)
409		if err != nil {
410			t.Fatal(err)
411		}
412		got, err := s2.GetSample("P")
413		if err != nil {
414			t.Fatal(err)
415		}
416		if got.Remaining != "0.000" || got.InitialQty != "3.125" {
417			t.Fatalf("重开后数量错误: %+v", got)
418		}
419		if got.Destruction == nil || got.Destruction.Operator != "张三" ||
420			got.Destruction.Location != "A" || got.Destruction.Reason != "污染" ||
421			got.Destruction.Qty != "3.125" || !got.Destruction.At.Equal(at) {
422			t.Fatalf("重开后销毁信息应保留: %+v", got.Destruction)
423		}
424		if len(got.History) != len(first.History) ||
425			got.History[len(got.History)-1].Kind != "destroy" {
426			t.Fatalf("重开后销毁历史应保留: %+v", got.History)
427		}
428	
429		// 重开后重复提交相同信息仍幂等。
430		again, err := s2.Destroy(DestroyInput{
431			SampleID: "P", Operator: " 张三 ", Location: "A", At: at, Reason: "污染",
432		})
433		if err != nil {
434			t.Fatalf("重开后相同销毁请求应幂等返回: %v", err)
435		}
436		if len(again.History) != len(got.History) {
437			t.Fatalf("幂等重复不得追加历史")
438		}
439		// 改任一项仍拒绝；分装与新交接仍被限制。
440		if _, err := s2.Destroy(DestroyInput{
441			SampleID: "P", Operator: "张三", Location: "A", At: at.Add(time.Minute), Reason: "污染",
442		}); !errors.Is(err, ErrConflict) {
443			t.Fatalf("重开后销毁幂等判断应继续生效, got %v", err)
444		}
445		if _, err := s2.Split(SplitInput{ParentID: "P", Parts: []SplitPart{{ID: "C", Qty: "0.001"}}}); !errors.Is(err, ErrConflict) {
446			t.Fatalf("重开后已销毁样品仍不得分装, got %v", err)
447		}
448		if _, err := s2.Handover(HandoverInput{
449			TransferID: "TR-X", SampleID: "P",
450			FromHolder: "张三", FromLocation: "A",
451			ToHolder: "李四", ToLocation: "B", HandedOverAt: at.Add(time.Hour),
452		}); !errors.Is(err, ErrConflict) {
453			t.Fatalf("重开后已销毁样品仍不得发起新交接, got %v", err)
454		}
455	}
456	
457	// TestDestroyLegacyDataWithoutDestruction 旧数据中没有销毁信息的样品一律
458	// 视为未销毁，即使剩余量为零也不能推断为销毁。
459	func TestDestroyLegacyDataWithoutDestruction(t *testing.T) {
